<script lang="ts">
  import {gradientScalingTrace,matrix2x2Trace,type FloatingPrecision} from '../../lib/curriculum';
  const left=[1.2345,-.3333,.0001,2.7183],right=[.7071,1.4142,-1.1111,.0625];
  const steps=[
    ['with torch.autocast(...):','autocast chooses a dtype for eligible forward operations'],
    ['loss = loss_fn(model(x), y)','the loss operation keeps the precision it needs'],
    ['scaler.scale(loss).backward()','a larger upstream sensitivity flows through the same graph'],
    ['scaler.step(optimizer)','unscale gradients, check finite values, then update or skip'],
    ['scaler.update()','adapt the scale for a later batch']
  ];
  let precision:FloatingPrecision='fp16',stage=0,gradientExponent=-8,scale=4096;
  $: matrix=matrix2x2Trace(left,right,precision);
  $: gradient=10**(+gradientExponent);
  $: gradientTrace=gradientScalingTrace(gradient,+scale,precision);
  const number=(value:number)=>!Number.isFinite(value)?'overflow':Math.abs(value)<.0001&&value!==0?value.toExponential(2):value.toFixed(5);
  const precisionLabel=(value:FloatingPrecision)=>value.toUpperCase();
</script>

<section class="lab" aria-labelledby="mixed-title">
  <header><div><span>Autograd bridge</span><h3 id="mixed-title">Same graph, different numeric representation</h3></div><nav aria-label="Computation precision">{#each ['fp32','fp16','bf16'] as item}<button class:active={precision===item} onclick={()=>precision=item as FloatingPrecision}>{item.toUpperCase()}</button>{/each}</nav></header>
  <div class="bridge"><a href="../gradient-sensitivity/"><b>M2 · sensitivity</b><span>∂loss / ∂node</span></a><i>→</i><a href="../computation-graphs/"><b>M2 · chain rule</b><span>multiply local slopes</span></a><i>→</i><div><b>loss scaling</b><span>multiply the upstream signal</span></div><i>→</i><div><b>optimizer</b><span>unscale before update</span></div></div>
  <div class="workspace">
    <div class="code">
      <div class="filebar">train_amp.py <small>click a line to trace it</small></div>
      <pre><code>scaler = torch.amp.GradScaler("cuda")
for x, y in loader:
    optimizer.zero_grad()</code></pre>
      {#each steps as item,index}<button class:active={stage===index} onclick={()=>stage=index}><i>{index+1}</i><span><code>{item[0]}</code><small>{item[1]}</small></span></button>{/each}
    </div>
    <div class="trace">
      <div class="trace-title"><div><small>selected stage</small><b>{steps[stage][0]}</b></div><span>{stage<2?'forward':stage===2?'backward':stage===3?'update gate':'next batch'}</span></div>
      <div class="matmul" class:muted={stage>1}>
        {@render Matrix('X · activation',left,matrix.roundedLeft,precision)}<strong>×</strong>{@render Matrix('W · parameter view',right,matrix.roundedRight,precision)}<strong>=</strong>{@render Matrix('Z · matmul output',matrix.reference,matrix.output,precision)}
      </div>
      <div class="matrix-facts"><span>graph edges <b>unchanged</b></span><span>matrix shapes <b>unchanged</b></span><span>tensor bytes <b>{matrix.bytesPerElement*12} B</b><small>3 toy matrices</small></span><span>max output |Δ| <b>{number(matrix.maxAbsoluteError)}</b></span></div>
      <div class="dtype-flow"><span><b>FP32 parameters</b><i></i></span><span class:active={stage===0}><b>{precisionLabel(precision)} matmul</b><i></i></span><span class:active={stage===1}><b>FP32 loss</b><i></i></span><span class:active={stage===2}><b>scaled backward</b><i></i></span><span class:active={stage===3}><b>FP32 update</b></span></div>
    </div>
  </div>
  <div class="gradient">
    <div class="gradient-copy"><small>Backward signal lab</small><h4>Can this sensitivity survive a lower-precision operation?</h4><p>The scale multiplies the loss, so the chain rule multiplies every downstream gradient by the same scale. Unscaling later restores its intended magnitude.</p></div>
    <div class="gradient-controls"><label>gradient magnitude <b>10<sup>{gradientExponent}</sup></b><input type="range" min="-12" max="-2" step="1" bind:value={gradientExponent}/></label><label>loss scale <select bind:value={scale}><option value={1}>1</option><option value={256}>256</option><option value={4096}>4,096</option><option value={65536}>65,536</option><option value={1048576}>1,048,576</option></select></label></div>
    <div class="gradient-flow"><span><small>original sensitivity</small><b>{number(gradientTrace.gradient)}</b></span><i>× {scale}</i><span><small>scaled before backward</small><b>{number(gradientTrace.scaledGradient)}</b></span><i>→ {precisionLabel(precision)} op</i><span class:danger={!gradientTrace.finite}><small>stored signal</small><b>{number(gradientTrace.storedScaledGradient)}</b></span><i>÷ {scale}</i><span><small>before optimizer step</small><b>{number(gradientTrace.restoredGradient)}</b></span></div>
    <footer>{#if precision==='bf16'}<b>BF16 range:</b> its FP32-sized exponent usually makes gradient scaling unnecessary, although rounding is coarser.{:else if precision==='fp32'}<b>FP32 baseline:</b> this scale is unnecessary; the signal already survives at full precision.{:else if gradientTrace.withoutScaling===0&&gradientTrace.storedScaledGradient!==0}<b>Scaling rescued this signal:</b> without scaling, FP16 rounds it to zero.{:else if !gradientTrace.finite}<b>Step skipped:</b> the scaled value overflowed; GradScaler lowers the scale for a later batch.{:else}<b>Finite path:</b> scaler.step() can unscale and pass the gradients to the optimizer.{/if}</footer>
  </div>
  <aside><b>What autocast does not do:</b> it does not rewrite the computation graph, halve every training byte, or make the optimizer update lower-precision parameters by default.</aside>
</section>

{#snippet Matrix(title:string,original:number[],rounded:number[],precision:FloatingPrecision)}
  <div class="matrix"><div><small>{title}</small><b>{precisionLabel(precision)}</b></div><div class="cells">{#each rounded as value,index}<span class:changed={value!==original[index]}>{number(value)}{#if value!==original[index]}<small>{number(original[index])}</small>{/if}</span>{/each}</div></div>
{/snippet}

